result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/engine.py", "content": """"Data-driven adventure game engine.

The world is fully described by a JSON file:
- rooms: name -> {desc, items}
- doors: list of {id, locked_by (item name or null), sides: [[room, direction], ...]}
- start: starting room
- win_room: room you must reach...
- required_item: ...while carrying this item.

Game state is an immutable tuple: (location, inventory frozenset, unlocked door-id frozenset).
"""

import json


class Game:
    def __init__(self, world):
        self.rooms = world["rooms"]
        self.start = world["start"]
        self.win_room = world["win_room"]
        self.required_item = world["required_item"]
        self.doors = {d["id"]: d for d in world["doors"]}
        # (room, direction) -> door id
        self.exits = {}
        for d in world["doors"]:
            for room, direction in d["sides"]:
                self.exits[(room, direction)] = d["id"]

    @classmethod
    def from_file(cls, path):
        with open(path) as f:
            return cls(json.load(f))

    # ----- state helpers -------------------------------------------------

    def initial_state(self):
        return (self.start, frozenset(), frozenset())

    def won(self, state):
        loc, inv, _unlocked = state
        return loc == self.win_room and self.required_item in inv

    def other_side(self, door_id, room):
        for r, _d in self.doors[door_id]["sides"]:
            if r != room:
                return r
        raise ValueError(f"door {door_id} has no side other than {room}")

    # ----- command execution ---------------------------------------------
    # Commands: "move <dir>", "take <item>", "unlock <dir>"
    # Returns the new state, or None if the command is illegal.

    def apply(self, state, command):
        loc, inv, unlocked = state
        parts = command.split(None, 1)
        if len(parts) != 2:
            return None
        verb, arg = parts[0], parts[1]

        if verb == "move":
            door_id = self.exits.get((loc, arg))
            if door_id is None or door_id not in unlocked:
                return None
            return (self.other_side(door_id, loc), inv, unlocked)

        if verb == "take":
            if arg not in self.rooms[loc]["items"] or arg in inv:
                return None
            return (loc, inv | {arg}, unlocked)

        if verb == "unlock":
            door_id = self.exits.get((loc, arg))
            if door_id is None or door_id in unlocked:
                return None
            needed = self.doors[door_id]["locked_by"]
            if needed is None or needed not in inv:
                return None
            return (loc, inv, unlocked | {door_id})

        return None

    def replay(self, commands):
        """Run a command sequence from the start; return final state."""
        state = self.initial_state()
        for cmd in commands:
            state = self.apply(state, cmd)
            if state is None:
                raise ValueError(f"illegal command {cmd!r}")
        return state
