from collections import deque


def solve(game):
    """Breadth-first search for a shortest winning command sequence.

    State: (location, frozenset(inventory), frozenset(unlocked door ids)).
    Returns the list of commands, or None if the game is unwinnable
    (the reachable state space is finite, so exhaustion = proof).
    """
    start = game.initial_state()
    if game.won(start):
        return []

    # parent[state] = (previous_state, command_that_led_here)
    parent = {start: None}
    queue = deque([start])

    while queue:
        state = queue.popleft()
        loc, inv, unlocked = state

        candidates = []
        for (room, direction), door_id in game.exits.items():
            if room == loc:
                if door_id in unlocked:
                    candidates.append(f"move {direction}")
                else:
                    needed = game.doors[door_id]["locked_by"]
                    if needed and needed in inv:
                        candidates.append(f"unlock {direction}")
        for item in game.rooms[loc]["items"]:
            if item not in inv:
                candidates.append(f"take {item}")

        for cmd in candidates:
            nxt = game.apply(state, cmd)
            if nxt is None or nxt in parent:
                continue
            parent[nxt] = (state, cmd)
            if game.won(nxt):
                # Reconstruct the path.
                cmds = []
                cur = nxt
                while parent[cur] is not None:
                    cur, c = parent[cur]
                    cmds.append(c)
                cmds.reverse()
                return cmds
            queue.append(nxt)

    return None  # search exhausted without a win -> provably unwinnable


def all_reachable_states(game):
    """Full BFS enumeration; returns the set of every reachable state."""
    start = game.initial_state()
    seen = {start}
    queue = deque([start])
    while queue:
        state = queue.popleft()
        loc, inv, unlocked = state
        candidates = []
        for (room, direction), door_id in game.exits.items():
            if room == loc:
                if door_id in unlocked:
                    candidates.append(("move", direction))
                elif (
                    game.doors[door_id]["locked_by"]
                    and game.doors[door_id]["locked_by"] in inv
                ):
                    candidates.append(("unlock", direction))
        for item in game.rooms[loc]["items"]:
            if item not in inv:
                candidates.append(("take", item))
        for verb, arg in candidates:
            nxt = game.apply(state, f"{verb} {arg}")
            if nxt is not None and nxt not in seen:
                seen.add(nxt)
                queue.append(nxt)
    return seen
